/* Contenu des leçons — français */
I18N.registerLessons("fr", {

/* ===================== PIANO ===================== */
"piano-1":{title:"À la rencontre des touches",goal:"Identifier n'importe quelle note du piano en cinq secondes",b:{
0:"Le piano fait peur : 88 touches. La vérité ? Il n'y a que <b>12 touches</b> qui se répètent encore et encore. Dès que vous voyez le motif, tout l'instrument s'ouvre.",
1:"Le secret est dans les touches noires : elles sont groupées par <b>deux</b> et par <b>trois</b>, en alternance. C'est votre carte.",
2:["Repérez un groupe de deux touches noires.","La touche blanche juste à leur gauche (vers les graves) est le <b>do (C)</b>.","Ensuite il suffit de suivre : do, ré, mi, fa, sol, la, si — puis do à nouveau.","Chaque do suivant est le même son, plus aigu. Cela s'appelle une <b>octave</b>."],
3:"Appuyez sur la touche surlignée — c'est le do (C4). Essayez de trouver les autres do.",
4:"<b>Conseil en or :</b> le do central (C4) se trouve à peu près au milieu du piano, face à la serrure ou au logo. C'est le point de repère de tout pianiste.",
5:"La gamme de do majeur — les sept notes blanches puis retour au do",
6:{q:"Comment repère-t-on la note do sur le piano ?",o:["La touche blanche à gauche de trois touches noires","La touche blanche collée au groupe de deux touches noires, du côté grave","La première touche noire","La touche blanche au milieu du clavier"],w:"Le do est toujours la touche blanche collée au groupe de deux noires, du côté des graves."},
7:"Installez-vous au clavier (réel ou à l'écran) et nommez à voix haute tous les do, puis tous les fa. Trois minutes suffisent."}},

"piano-2":{title:"La main droite — cinq doigts, cinq notes",goal:"Jouer do–ré–mi–fa–sol d'affilée sans regarder ses mains",b:{
0:"Au piano chaque doigt a un numéro : <b>1 = pouce</b>, 2 = index, 3 = majeur, 4 = annulaire, 5 = auriculaire. La numérotation est la même aux deux mains.",
1:"Posez le pouce droit sur le <b>do (C4)</b> et chaque doigt suivant sur la touche blanche suivante. Vos cinq doigts sont exactement sur do-ré-mi-fa-sol. C'est la « position de do » — la première position que tout pianiste apprend.",
2:"Position de do — doigts 1, 2, 3, 4, 5",
3:["Arrondissez légèrement les doigts, comme si vous teniez une petite orange.","Gardez le poignet droit — ni creusé ni relevé.","Jouez 1-2-3-4-5 lentement, chaque note au même volume.","Redescendez : 5-4-3-2-1.","Quand cela coule, fermez les yeux et rejouez."],
4:"<b>L'égalité du son compte plus que la vitesse.</b> Le doigt faible (4) cherchera toujours à jouer moins fort. Accordez-lui une attention particulière.",
5:"Exercice de doigts nº 1",
6:{q:"Quel doigt porte le numéro 1 au piano ?",o:["L'auriculaire","Le majeur","Le pouce","L'index"],w:"Le pouce est toujours le doigt numéro 1 — aux deux mains."},
7:"Jouez l'exercice cinq fois de suite sans faute. En cas d'erreur, recommencez plus lentement."}},

"piano-3":{title:"Votre premier morceau",goal:"Jouer une mélodie complète d'oreille et sur la partition",b:{
0:"Le moment est venu : vous jouez un morceau. « Ah ! vous dirai-je, maman » est une mélodie populaire française du XVIIIᵉ siècle (domaine public) — Mozart en a même écrit des variations.",
1:"Toutes les notes sont dans la position de do apprise, sauf le <b>la (A4)</b>, que l'on atteint en déplaçant légèrement l'auriculaire.",
2:"Ah ! vous dirai-je, maman — la mélodie complète",
3:"Les notes nécessaires au morceau",
4:["Écoutez la mélodie deux fois avec le bouton de lecture.","Jouez seulement les quatre premières notes : do do sol sol.","Ajoutez : la la sol (le sol est long — deux temps).","Continuez : fa fa mi mi ré ré do.","Reliez le tout lentement, et seulement ensuite ajoutez de la vitesse."],
5:"<b>La règle clé de l'apprentissage autonome :</b> lentement = vite. Un cerveau qui apprend lentement et sans erreur atteint la vitesse trois fois plus rapidement.",
6:{q:"À quel tempo faut-il commencer un nouveau morceau ?",o:["Le plus vite possible","Au tempo où vous jouez sans faute","Au tempo d'origine du morceau","Cela n'a pas d'importance"],w:"Le bon tempo est celui où vous y arrivez sans erreur. La vitesse vient ensuite d'elle-même."},
7:"Jouez le morceau trois fois de suite sans vous arrêter."}},

"piano-4":{title:"Le rythme — la langue du temps",goal:"Compter 1-2-3-4 et jouer différentes valeurs",b:{
0:"La musique n'est pas seulement quelles notes — c'est aussi <b>quand</b>. Les valeurs de base :",
1:["<b>Ronde</b> — dure 4 temps.","<b>Blanche</b> — 2 temps.","<b>Noire</b> — un temps. C'est la valeur la plus courante.","<b>Croche</b> — un demi-temps. On compte 1-et-2-et."],
2:"Exercice de rythme — compter à quatre",
3:"La plupart des chansons populaires ont <b>quatre temps par mesure</b> (4/4). Le premier temps est plus fort — c'est le pouls du morceau.",
4:"On frappe dans les mains d'abord, on joue ensuite. Si vous n'arrivez pas à frapper un rythme, vous n'arriverez pas à le jouer.",
5:"Même note, valeurs différentes",
6:{q:"Combien de temps dure une noire en 4/4 ?",o:["4","2","1","Un demi"],w:"Une noire = un temps. Quatre noires remplissent une mesure complète."},
7:"Réglez le métronome sur 70 et frappez exactement sur les temps. Puis frappez les croches (deux fois par temps)."}},

"piano-5":{title:"La main gauche entre en scène",goal:"Jouer une basse simple de la main gauche",b:{
0:"La main gauche joue les sons graves — la base harmonique. Commençons simplement : une note par mesure.",
1:"Do et sol dans l'octave de la main gauche",
2:["Posez l'auriculaire gauche sur do (C3).","Posez le pouce sur sol (G3).","Jouez do — comptez 4. Jouez sol — comptez 4.","Quand c'est stable, jouez do-sol-do-sol sur les temps 1 et 3."],
3:"La main gauche paraît toujours « bête » au début. C'est parfaitement normal — elle a simplement moins travaillé dans la vie. En une semaine elle rattrape.",
4:"Exercice de basse",
5:{q:"Quel est le rôle principal de la main gauche dans le piano populaire ?",o:["Jouer la mélodie","Jouer la basse et l'harmonie","Tourner les pages","Tenir le tempo uniquement"],w:"La main gauche construit la base harmonique sur laquelle repose la mélodie de la main droite."},
6:"Jouez l'exercice de basse avec le métronome à 70."}},

"piano-6":{title:"Les deux mains ensemble — le grand moment",goal:"Coordonner les mains dans un exercice simple",b:{
0:"C'est là que la plupart des autodidactes bloquent, pour une seule raison : ils réunissent les mains trop tôt.",
1:["Jouez la main droite seule jusqu'à ce qu'elle soit totalement automatique.","Faites de même avec la main gauche.","Jouez une seule mesure à deux mains — et arrêtez.","Ajoutez une mesure à la fois.","Si vous bloquez, revenez aux mains séparées. Toujours."],
2:"Exercice à deux mains (la mélodie)",
3:"Exercice à deux mains (la basse)",
4:"<b>Une astuce qui marche :</b> dites à voix haute les notes de la main droite en jouant. Cela force le cerveau à séparer les mains.",
5:{q:"Que faire quand on n'arrive pas à réunir les deux mains ?",o:["Jouer plus vite","Abandonner la main gauche","Revenir aux mains séparées et n'assembler qu'une mesure","Passer à un autre morceau"],w:"Découper en petits morceaux et reconstruire progressivement est la seule méthode qui fonctionne."},
6:"Jouez les deux exercices ensemble, deux mesures seulement, dix fois."}},

"piano-7":{title:"Gamme de do majeur et passage du pouce",goal:"Jouer une octave complète d'une main",b:{
0:"Vous n'avez que cinq doigts — et la gamme compte huit notes. La solution : le <b>passage du pouce</b>, le mouvement le plus important de la technique pianistique.",
1:"Gamme de do majeur ascendante",
2:["Main droite : 1-2-3 sur do-ré-mi.","Pendant que le doigt 3 joue mi, le pouce « passe » sous la paume.","Le pouce se pose sur fa — et de là 1-2-3-4-5 jusqu'au do suivant.","Le doigté complet : 1 2 3 1 2 3 4 5.","En descendant : 5 4 3 2 1 3 2 1."],
3:"Le coude et l'avant-bras doivent accompagner légèrement la main vers la droite. Si seul le pouce bouge, ce sera maladroit.",
4:"Gamme de do majeur — aller et retour",
5:{q:"Quand le pouce passe-t-il sous la paume dans une gamme de do majeur ascendante ?",o:["Après la note ré","Pendant que le doigt 3 joue mi","Après sol","Il ne passe pas"],w:"Le passage se fait pendant que le doigt 3 joue mi, pour que le pouce arrive à temps sur fa."},
6:"Jouez la gamme aller-retour quatre fois au métronome à 60."}},

"piano-8":{title:"Les accords — trois notes qui changent tout",goal:"Jouer C, F et G de la main gauche",b:{
0:"Un <b>accord</b>, ce sont trois notes ou plus jouées ensemble. Un accord majeur se construit en sautant : note, on saute, note, on saute, note.",
1:"Accord de do majeur (C) — do-mi-sol",
2:"Accord de fa majeur (F) — fa-la-do",
3:"Accord de sol majeur (G) — sol-si-ré",
4:"Ces trois accords (C, F, G) suffisent pour des centaines de morceaux. Ce sont les « trois grands » de la tonalité.",
5:"Remarquez que chaque accord se construit pareil : doigts 5-3-1 à la main gauche, sur une touche blanche, on saute, touche, on saute, touche.",
6:{q:"De quelles notes se compose l'accord de do majeur ?",o:["do-ré-mi","do-mi-sol","do-fa-la","do-sol-do"],w:"Un accord majeur se construit sur les 1er, 3e et 5e degrés de la gamme : do-mi-sol."},
7:"Passez de C à F puis à G, quatre temps par accord, métronome à 60."}},

"piano-9":{title:"L'accompagnement — jouer un morceau avec des accords",goal:"Combiner la mélodie à droite et les accords à gauche",b:{
0:"On réunit tout : la main gauche joue un accord, la main droite la mélodie. C'est ainsi qu'on accompagne n'importe quel morceau au monde.",
1:["Jouez « Ah ! vous dirai-je, maman » de la main droite.","Première mesure — accord C à la main gauche.","Quand la mélodie arrive à « la la sol » — passez à F puis à C.","Dans l'avant-dernière mesure — G, et pour finir de nouveau C."],
2:"Mélodie à travailler",
3:"<b>Comment savoir quel accord convient ?</b> Regardez quel accord contient la note que la mélodie joue sur ce temps. Si la mélodie joue mi, C conviendra (do-mi-sol).",
4:{q:"Quel accord contient la note la ?",o:["C (do-mi-sol)","G (sol-si-ré)","F (fa-la-do)","Aucun"],w:"L'accord de F est fait de fa-la-do, il contient donc la note la."},
5:"Jouez le morceau avec l'accompagnement, très lentement, deux fois."}},

"piano-10":{title:"Majeur et mineur — la couleur émotionnelle",goal:"Reconnaître et jouer les accords mineurs",b:{
0:"La différence entre « gai » et « triste » en musique, c'est <b>un demi-ton</b>. Déplacez la note du milieu d'un accord majeur d'une touche vers la gauche : vous avez un accord mineur.",
1:"Accord de la mineur (Am) — la-do-mi",
2:"Accord de ré mineur (Dm) — ré-fa-la",
3:"Accord de mi mineur (Em) — mi-sol-si",
4:"Jouez C puis Am l'un après l'autre. Remarquez comme l'humeur du son change instantanément. C'est la puissance de l'harmonie.",
5:{q:"Quelle est la différence entre un accord majeur et un accord mineur ?",o:["Le mineur est plus aigu","La note du milieu du mineur est plus basse d'un demi-ton","Le mineur a quatre notes","Il n'y a pas de vraie différence"],w:"La note du milieu (la tierce) descend d'un demi-ton — et c'est toute la différence entre « gai » et « triste »."},
6:"Jouez la suite C – Am – F – G, quatre temps par accord. C'est la suite la plus répandue de la musique populaire."}},

"piano-11":{title:"Nuances, pédale et expression",goal:"Transformer un jeu technique en jeu musical",b:{
0:"Deux personnes joueront les mêmes notes — et l'une sonnera comme un robot. La différence, c'est la <b>nuance</b> : la variation du volume.",
1:["<b>Piano (p)</b> — doux. <b>Forte (f)</b> — fort.","<b>Crescendo</b> — de plus en plus fort. <b>Diminuendo</b> — de plus en plus doux.","Jouez la gamme : commencez doucement, culminez sur le do aigu, et affaiblissez en descendant.","Une phrase musicale est comme une phrase parlée — elle a un début, un sommet et une fin."],
2:"<b>La pédale de droite</b> (pédale forte) lève les étouffoirs des cordes — et le son continue de résonner. La règle : changer de pédale à chaque changement d'accord, sinon cela devient une bouillie.",
3:"La bonne technique : on enfonce la pédale <b>juste après</b> que le doigt a joué, pas avant. On appelle cela la « pédale retardée ».",
4:{q:"Quand change-t-on de pédale ?",o:["À chaque note","À chaque changement d'accord","Seulement à la fin du morceau","Jamais, on la garde enfoncée"],w:"Changer de pédale à chaque changement d'accord garde le son propre."},
5:"Jouez la gamme avec un crescendo en montant et un diminuendo en descendant."}},

"piano-12":{title:"Morceau final — Ode à la joie",goal:"Jouer une œuvre classique complète",b:{
0:"Vous avez terminé le parcours de base. Il est temps de jouer une vraie œuvre : le thème de la Neuvième symphonie de Beethoven (1824) — domaine public.",
1:"Ode à la joie",
2:["Jouez la main droite seule, quatre mesures à la fois.","Ajoutez une basse simple à gauche : C – C – G – C.","Ajoutez les nuances : début calme, sommet au milieu.","Ajoutez la pédale aux changements d'accord.","Jouez du début à la fin sans vous arrêter — même en cas de faute."],
3:"<b>La règle du musicien expérimenté :</b> en interprétation on ne s'arrête pas pour corriger. On continue. Les corrections appartiennent au travail, pas au jeu.",
4:{q:"Quelle est la façon la plus efficace de travailler un nouveau morceau ?",o:["Le jouer en entier encore et encore","Isoler les passages difficiles et ne travailler qu'eux","Ne jouer que les parties faciles","Se contenter d'écouter des enregistrements"],w:"Le travail ciblé sur les passages difficiles fait gagner des heures. 80 % du temps doit aller aux 20 % les plus durs."},
5:"Enregistrez-vous (avec votre téléphone) et réécoutez. Vous entendrez des choses que vous n'aviez pas remarquées en jouant."}},

/* ===================== GUITARE ===================== */
"guitar-1":{title:"À la rencontre de la guitare et de la bonne posture",goal:"Bien s'asseoir, bien tenir et accorder la guitare",b:{
0:"La guitare a six cordes. La plus grosse (en haut) est le <b>mi grave (E)</b>, la plus fine (en bas) le <b>mi aigu (E)</b>. La numérotation va <b>de la fine à la grosse</b> : la plus fine est la corde 1.",
1:["Corde 6 — mi grave (E2)","Corde 5 — la (A2)","Corde 4 — ré (D3)","Corde 3 — sol (G3)","Corde 2 — si (B3)","Corde 1 — mi aigu (E4)"],
2:"Le son des cordes à vide — de la grosse à la fine",
3:"<b>Bien s'asseoir :</b> dos droit, caisse de la guitare sur la jambe droite (pour un droitier), manche légèrement relevé. Pouce de la main gauche derrière le manche — il ne dépasse pas par-dessus.",
4:"Des bouts de doigts douloureux les deux premières semaines, c'est normal — la peau durcit. Une douleur au poignet ou à l'épaule n'est <b>pas</b> normale et signale une mauvaise posture. Arrêtez et corrigez votre position.",
5:"Accordez la guitare avant chaque séance. Une guitare désaccordée apprend de fausses hauteurs à votre oreille. Utilisez l'<a href='#/tools/tuner'>accordeur de l'application</a>.",
6:{q:"Quelle corde porte le numéro 1 ?",o:["La plus grosse","La plus fine","Celle du milieu","Cela dépend de la guitare"],w:"La corde 1 est la plus fine — le mi aigu."},
7:"Accordez la guitare, puis jouez chaque corde à vide et dites son nom à voix haute."}},

"guitar-2":{title:"La main droite — votre premier grattage",goal:"Produire un son propre et régulier sur les cordes à vide",b:{
0:"La main droite est responsable du son et du rythme. On peut jouer au médiator ou aux doigts — nous commencerons au médiator.",
1:["Tenez le médiator entre le pouce et l'index, avec seulement 3 à 5 mm qui dépassent.","Le mouvement vient du poignet, pas du coude.","Grattez vers le bas sur les six cordes — un seul son continu.","Puis vers le haut, de la corde fine vers la grosse.","Travaillez : bas, bas, bas, bas — à tempo régulier."],
2:"Grattages en noires — quatre temps",
3:"Si le son « accroche », vous serrez probablement trop le médiator. Une prise relâchée donne un son fluide.",
4:{q:"D'où doit venir le mouvement de grattage ?",o:["De l'épaule","Du coude","Du poignet","Des doigts seulement"],w:"Un mouvement de poignet est relâché, rapide et n'entraîne pas de blessures."},
5:"Grattez les cordes à vide pendant 2 minutes d'affilée au métronome à 70. Surveillez la régularité du son."}},

"guitar-3":{title:"Le premier accord — Em",goal:"Jouer un accord propre et le gratter en rythme",b:{
0:"Em (mi mineur) est l'accord le plus facile du monde : deux doigts seulement, et les six cordes se jouent.",
1:null,
2:["Doigt 2 sur la case 2 de la corde 5 (la).","Doigt 3 sur la case 2 de la corde 4 (ré).","Appuyez près de la frette — ni dessus ni au milieu.","Les doigts sont sur leur pointe, ils ne sont pas couchés.","Jouez corde par corde et vérifiez que chacune sonne proprement."],
3:"Un son « mort » ou qui frise ? La cause est presque toujours un doigt couché qui touche une corde voisine. Relevez la paume et arrondissez davantage les doigts.",
4:"La méthode de vérification des professeurs : jouez chaque corde séparément (un « arpège »). La corde qui ne sonne pas vous indique exactement quel doigt corriger.",
5:{q:"Que faire quand une corde de l'accord frise ?",o:["Appuyer plus fort avec tous les doigts","Vérifier quel doigt est couché et touche une corde voisine","Réaccorder la guitare","Changer les cordes"],w:"Dans 90 % des cas, un doigt voisin touche la corde. La solution est d'arrondir les doigts, pas la force."},
6:"Tenez Em et grattez 16 temps d'affilée. Relâchez, secouez la main, et recommencez — cinq fois."}},

"guitar-4":{title:"Un deuxième accord et le premier changement",goal:"Passer de Em à Am sans s'arrêter",b:{
0:"Am (la mineur) est exactement la même forme que Em — simplement décalée d'une corde, avec un doigt en plus.",
1:null,
2:["Prenez la forme de Em et décalez-la d'une corde vers les cordes fines.","Ajoutez le doigt 1 sur la case 1 de la corde 2 (si).","Ne grattez pas la corde 6.","Passez Em → Am → Em → Am, sans gratter — seulement la main."],
3:"<b>Le secret des changements :</b> travaillez le passage <u>sans gratter</u>, 20 fois. Le cerveau apprend le mouvement sans la pression du son. Ajoutez le grattage ensuite.",
4:"<b>Doigt d'ancrage :</b> entre Em et Am, deux doigts gardent la même forme. Ne levez pas toute la main — faites-la glisser.",
5:{q:"Quelle est la façon la plus efficace de travailler un changement d'accord ?",o:["Jouer le morceau vite, encore et encore","Travailler le mouvement de la main seul, sans gratter","Travailler chaque accord séparément","Ne travailler qu'avec un métronome rapide"],w:"Séparer le mouvement de la main du grattage permet au cerveau d'apprendre le geste proprement et vite."},
6:"60 changements Em↔Am. Comptez à voix haute. Quatre minutes qui changent tout."}},

"guitar-5":{title:"La rythmique — bas et haut",goal:"Jouer la rythmique d'accompagnement la plus répandue",b:{
0:"La rythmique la plus fondamentale : <b>bas, bas-haut, haut-bas-haut</b>. Si vous n'apprenez qu'une seule rythmique dans votre vie, que ce soit celle-là.",
1:["Comptez à voix haute : 1 et 2 et 3 et 4 et.","La main monte et descend en permanence — comme un pendule, sans jamais s'arrêter.","Sur les temps où l'on ne joue pas, la main continue son mouvement en l'air, elle ne touche simplement pas.","Le schéma : ↓ . ↓↑ . ↑↓↑ (1, 2-et, 3-et-4-et)."],
2:"La rythmique d'accompagnement de base",
3:"La main qui ne s'arrête jamais, voilà le secret. Les débutants stoppent la main — et perdent le rythme. Laissez-la toujours bouger.",
4:{q:"Pourquoi la main droite doit-elle continuer à bouger même sans gratter ?",o:["Pour l'allure","Pour garder une sensation continue du rythme","Pour ne pas fatiguer la main","Ce n'est pas important"],w:"Le mouvement continu est votre horloge interne. S'arrêter casse le rythme."},
5:"Jouez Em avec cette rythmique pendant une minute entière sans vous arrêter, puis Am."}},

"guitar-6":{title:"L'accord de C — et un changement plus délicat",goal:"Jouer un C propre et l'intégrer à une suite",b:{
0:"C (do majeur) demande trois doigts sur trois cases différentes. C'est l'accord qui sépare ceux qui persévèrent de ceux qui abandonnent.",
1:null,
2:["Doigt 1 — case 1, corde 2.","Doigt 2 — case 2, corde 4.","Doigt 3 — case 3, corde 5.","Ne grattez pas la corde 6.","Vérifiez que les cordes à vide 1 et 3 sonnent librement."],
3:"Si la corde 1 (la fine) ne sonne pas, c'est votre doigt 1 qui est couché dessus. Tournez légèrement le poignet vers l'avant.",
4:{q:"Quelles cordes ne joue-t-on pas dans un accord de C ouvert ?",o:["La corde 1","La corde 6","Les cordes 5 et 6","On joue toutes les cordes"],w:"Dans l'accord de C on part de la cinquième corde. La sixième ne fait pas partie de l'accord."},
5:"Travaillez C → Am → C → Am, quatre temps chacun."}},

"guitar-7":{title:"G et D — votre premier morceau à trois accords",goal:"Jouer un morceau complet avec G, C et D",b:{
0:"Avec G, C et D on peut jouer des milliers de morceaux. C'est la « famille de sol » — les trois accords centraux de la tonalité de sol majeur.",
1:null,2:null,
3:"<b>La structure classique :</b> G – G – C – C – G – G – D – C – G. Quatre temps par accord.",
4:"Rythmique d'accompagnement pour le morceau",
5:"Notez qu'en passant de G à C, le doigt 3 peut rester sur la même case — c'est un « doigt d'ancrage » qui divise par deux la durée du changement.",
6:{q:"Qu'ont en commun les accords G, C et D ?",o:["Ils sont tous mineurs","Ce sont les trois accords centraux de la gamme de sol majeur","Ils sont sur la même case","Ils utilisent les mêmes doigts"],w:"Ce sont les degrés I, IV et V de la gamme de sol majeur — le squelette harmonique de la plupart des chansons."},
7:"Jouez le cycle G-C-G-D deux fois sans vous arrêter, même si les changements sont lents."}},

"guitar-8":{title:"Changements rapides et doigts d'ancrage",goal:"Raccourcir le temps de passage entre accords",b:{
0:"Les changements lents sont le problème numéro un des guitaristes débutants. La solution n'est ni la force ni la vitesse — c'est l'<b>efficacité</b>.",
1:["<b>Doigt d'ancrage :</b> repérez un doigt qui reste en place entre deux accords — ne le levez pas.","<b>Mouvement minimal :</b> ne levez les doigts que de 2 mm au-dessus des cordes.","<b>Timing :</b> changez d'accord sur le dernier temps, pas après.","<b>L'exercice de l'horloge :</b> lancez une minute et comptez vos changements propres. Battez votre record chaque jour."],
2:"Notez votre record de changements dans le journal de pratique de l'application. Un progrès mesurable est le plus puissant moteur de constance.",
3:{q:"Qu'est-ce qu'un « doigt d'ancrage » ?",o:["Le pouce derrière le manche","Un doigt qui reste en place lors du passage entre deux accords","Le doigt le plus fort","Un doigt qui appuie deux cordes"],w:"Un doigt d'ancrage raccourcit le changement et sert de repère aux autres doigts."},
4:"Une minute de changements C↔G. Notez le nombre. Revenez demain et battez-le."}},

"guitar-9":{title:"Rythmiques — varier l'accompagnement",goal:"Connaître trois rythmiques différentes",b:{
0:"Les mêmes accords avec une autre rythmique sonnent comme un morceau totalement différent. Voici trois rythmiques qui couvrent presque tous les styles.",
1:"Rythmique 1 — ballade lente",
2:"Rythmique 2 — pop standard",
3:"Rythmique 3 — rythmique à contretemps",
4:"<b>La rythmique à contretemps</b> — on ne gratte que sur les « et » entre les temps — donne une sensation rebondissante et convient au reggae, au ska et à de nombreux styles folk.",
5:{q:"Qu'est-ce qui change quand on joue les mêmes accords avec une autre rythmique ?",o:["L'harmonie","Le caractère et le style du morceau","La hauteur des sons","La vitesse seulement"],w:"C'est la rythmique qui définit le style. Les mêmes quatre accords peuvent sonner ballade, rock ou reggae."},
6:"Jouez la même suite d'accords avec les trois rythmiques."}},

"guitar-10":{title:"Votre premier solo — la gamme pentatonique",goal:"Improviser un court solo sur cinq notes",b:{
0:"La gamme pentatonique (cinq notes) est le secret de tout soliste de rock et de blues. Sa magie : il est presque impossible d'y jouer une « fausse » note.",
1:"Pentatonique mineure de la — ascendante",
2:["Placez le doigt 1 sur la case 5, corde 6 (la).","Le motif : 5-8 sur les cordes 6 et 5, 5-7 sur les cordes 4 et 3, 5-8 sur les cordes 2 et 1.","Jouez le motif dans les deux sens jusqu'à ce que les doigts le retiennent.","Oubliez maintenant l'ordre — jouez les notes au hasard. C'est de l'improvisation."],
3:"Un bon solo, ce n'est pas beaucoup de notes — ce sont des notes avec des <b>silences</b> entre elles. Laissez de la place pour respirer.",
4:{q:"Pourquoi la gamme pentatonique est-elle facile à improviser ?",o:["Elle n'a que des notes aiguës","Elle contient 5 notes qui conviennent toutes harmoniquement","On ne peut la jouer que sur une corde","Elle se joue lentement"],w:"Les notes « qui frottent » ont été retirées de la gamme — donc toutes leurs combinaisons sonnent bien."},
5:"Improvisez 8 mesures dans la pentatonique sur un métronome."}},

"guitar-11":{title:"Familles d'accords — A, E, Dm",goal:"Porter votre réserve d'accords à huit",b:{
0:null,1:null,2:null,
3:"Avec les huit accords appris (Em, Am, C, G, D, A, E, Dm) vous pouvez jouer la grande majorité des chansons populaires.",
4:"<b>La règle de correspondance :</b> les accords d'une même « famille » (tonalité) sonnent bien ensemble. Famille de do : C, Dm, Em, F, G, Am. Famille de sol : G, Am, Bm, C, D, Em.",
5:{q:"Quel accord n'appartient pas à la famille de sol majeur ?",o:["C","D","Em","F"],w:"F ne fait pas partie de la gamme de sol majeur (qui contient un fa dièse). Il appartient à la famille de do."},
6:"Choisissez quatre accords d'une même famille et jouez-les en boucle."}},

"guitar-12":{title:"Morceau final et coup d'œil vers la suite — le barré",goal:"Jouer un morceau complet et découvrir l'étape suivante",b:{
0:"Vous avez terminé le parcours de base. Vous savez accorder, gratter, jouer huit accords, trois rythmiques et un solo.",
1:"Mélodie de conclusion — Amazing Grace (domaine public)",
2:"<b>L'étape suivante : l'accord barré.</b> Le doigt 1 se couche sur toutes les cordes et imite un capodastre. Cela ouvre tout le manche.",
3:["Posez le doigt 1 à plat sur les six cordes à la case 1.","Utilisez le côté extérieur du doigt, pas la pulpe molle.","Ajoutez la forme de E avec les doigts 2, 3 et 4 — vous obtenez un F.","Ne vous découragez pas : un barré propre demande 2 à 4 semaines à la plupart des élèves."],
4:"Si vous ressentez une douleur au poignet en faisant un barré, arrêtez. Le problème est l'angle du pouce, pas un manque de force. Travaillez à la case 5, où les cordes sont plus souples.",
5:{q:"Qu'est-ce qu'un accord barré ?",o:["Un accord joué uniquement sur cordes à vide","Un accord où un doigt appuie plusieurs cordes à la fois","Un accord de quatre notes","Un accord rapide"],w:"Le doigt 1 crée un « sillet mobile », ce qui permet de déplacer les formes d'accords partout sur le manche."},
6:"Jouez un morceau complet de la bibliothèque avec accompagnement et enregistrez-vous."}},

/* ===================== UKULÉLÉ ===================== */
"ukulele-1":{title:"Le ukulélé en 10 minutes",goal:"Jouer un premier accord et le gratter",b:{
0:"Le ukulélé est l'instrument le plus rapide au monde pour commencer : quatre cordes en nylon souples et un accordage standard <b>G-C-E-A</b>.",
1:"Les cordes à vide",2:null,
3:["Maintenez le ukulélé contre vous avec l'avant-bras droit.","Placez le doigt 3 sur la case 3 de la corde fine (la).","Grattez doucement vers le bas avec la pulpe de l'index.","C'est tout — vous venez de jouer un accord de do."],
4:"Sur le ukulélé, on gratte à l'endroit où le manche rejoint la caisse — c'est là que le son est le plus plein.",
5:{q:"Quel est l'accordage standard d'un ukulélé soprano ?",o:["E-A-D-G","G-C-E-A","C-F-A-D","D-G-B-E"],w:"G-C-E-A est l'accordage standard, et le sol est en réalité plus aigu que le do (« accordage aigu »)."},
6:"Grattez l'accord de C pendant une minute à tempo régulier."}},

"ukulele-2":{title:"Deux accords = un morceau entier",goal:"Passer de C à Am",b:{
0:null,
1:"Am ne demande lui aussi qu'un seul doigt — le doigt 2 sur la case 2 de la corde grosse (sol).",
2:"Rythmique simple — quatre coups vers le bas",
3:"Jouez quatre temps de C, quatre temps de Am, et recommencez. C'est déjà une forme de chanson légitime sur laquelle on peut chanter.",
4:{q:"Combien de doigts faut-il pour l'accord Am au ukulélé ?",o:["Un","Deux","Trois","Quatre"],w:"Un seul doigt, sur la case 2 de la corde grosse."},
5:"30 changements C↔Am avec un métronome lent."}},

"ukulele-3":{title:"Le troisième accord — F",goal:"Jouer une suite de trois accords",b:{
0:null,
1:"Avec C, Am et F on peut déjà jouer des centaines de morceaux. La suite C – Am – F – C est un classique.",
2:"Rythmique pop",
3:{q:"Quelle suite courante utilise ces trois accords ?",o:["F – F – F – F","C – Am – F – C","C – C# – D","Am uniquement"],w:"C – Am – F est l'une des suites les plus fréquentes de la musique populaire."},
4:"Jouez la suite C-Am-F-C quatre fois d'affilée."}},

"ukulele-4":{title:"Rythmiques et variations",goal:"Trois rythmiques d'accompagnement",b:{
0:"Rythmique des îles",1:"Valse — trois temps",
2:"La rythmique « des îles » (bas, bas-haut, haut-bas-haut) est le son classique du ukulélé.",
3:"Gardez la main droite totalement relâchée. Au ukulélé, la force donne un son rugueux.",
4:{q:"Combien de temps y a-t-il dans une mesure de valse ?",o:["2","3","4","6"],w:"La valse est à 3/4 — trois temps par mesure, avec l'accent sur le premier."},
5:"Jouez la suite apprise avec deux rythmiques différentes."}},

"ukulele-5":{title:"G et Em — ouvrir le répertoire",goal:"Maîtriser cinq accords",b:{
0:null,1:null,
2:"G demande trois doigts en triangle, et Em est une diagonale descendante. Les deux exigent d'abord un travail lent.",
3:"Travaillez le passage C→G sans gratter, 20 fois. Vous constaterez que la main « apprend » la forme en quelques minutes.",
4:{q:"Qu'est-ce qui aide le plus à maîtriser un nouveau changement d'accord ?",o:["Jouer vite","Travailler le mouvement sans gratter","Appuyer plus fort","Changer les cordes"],w:"Séparer le mouvement du son accélère l'apprentissage moteur."},
5:"30 changements C↔G et 30 changements Am↔Em."}},

"ukulele-6":{title:"Le picking",goal:"Jouer un arpège de base",b:{
0:"Au lieu de gratter toutes les cordes ensemble, nous les pincerons l'une après l'autre — cela s'appelle un <b>arpège</b> et convient aux morceaux calmes.",
1:["Pouce — corde 4 (sol).","Index — corde 3 (do).","Majeur — corde 2 (mi).","Annulaire — corde 1 (la).","Jouez 4-3-2-1 puis 1-2-3-4."],
2:"Arpège sur l'accord de C",
3:{q:"Qu'est-ce qu'un arpège ?",o:["Un grattage fort","Jouer les notes d'un accord l'une après l'autre","Un changement d'accord rapide","Un type de médiator"],w:"Arpège = « accord brisé » : les notes sont jouées à la suite et non ensemble."},
4:"Jouez un arpège sur C, Am et F, quatre temps chacun."}},

"ukulele-7":{title:"La mélodie au ukulélé",goal:"Jouer une mélodie, pas seulement un accompagnement",b:{
0:"Le ukulélé sait aussi jouer des mélodies. Nous utiliserons les cordes do, mi et la.",
1:"Ah ! vous dirai-je, maman — mélodie",
2:"Repérez d'abord les notes sur le manche avec de petits autocollants — c'est un raccourci parfaitement légitime.",
3:{q:"Quel est l'intérêt de jouer des mélodies sur son instrument ?",o:["C'est plus facile que les accords","Cela entraîne l'oreille et la connaissance de l'emplacement des notes","Cela sonne plus fort","Il n'y a aucun intérêt"],w:"Jouer la mélodie relie l'oreille au manche — une compétence irremplaçable."},
4:"Jouez la mélodie deux fois lentement."}},

"ukulele-8":{title:"Chanter et jouer en même temps",goal:"Combiner accompagnement et chant",b:{
0:"C'est la compétence qui fait de vous la personne qu'on invite autour du feu. Le secret est l'<b>automatisme</b> : la main doit jouer sans que vous y pensiez.",
1:["Jouez l'accompagnement jusqu'à pouvoir tenir une conversation en même temps.","Dites les paroles en rythme, sans chanter.","Fredonnez la mélodie tout en jouant.","Seulement maintenant — chantez paroles et mélodie ensemble."],
2:"Si le chant « entraîne » la main, arrêtez de chanter, stabilisez la main, et réessayez. La main est l'ancre.",
3:{q:"Quelle est la condition pour chanter et jouer en même temps ?",o:["Une belle voix","Que l'accompagnement soit totalement automatique","Des accords compliqués","Un métronome"],w:"Un accompagnement automatique libère l'attention pour le chant."},
4:"Jouez l'accompagnement en fredonnant une mélodie pendant une minute complète."}},

"ukulele-9":{title:"Morceau final et coup d'œil vers la suite",goal:"Jouer un morceau complet du début à la fin",b:{
0:"Hava Naguila — mélodie traditionnelle (domaine public)",
1:"Les étapes suivantes au ukulélé : les accords barrés, la technique du « chunk » (étouffement rythmique) et le picking avancé.",
2:"Trouvez quelqu'un avec qui jouer. Jouer ensemble améliore le sens du rythme bien plus que n'importe quel travail solitaire.",
3:{q:"Quelle est l'étape recommandée après la maîtrise des accords ouverts ?",o:["Changer d'instrument","Les accords barrés et les rythmiques avancées","Arrêter de travailler","N'apprendre que le solfège"],w:"Le barré ouvre tout le manche et permet de jouer dans n'importe quelle tonalité."},
4:"Enregistrez-vous en train de jouer un morceau complet."}},

/* ===================== FLÛTE À BEC ===================== */
"recorder-1":{title:"Souffle et premier doigté",goal:"Produire un son propre et jouer si",b:{
0:"La flûte à bec est l'instrument parfait pour commencer : peu chère, légère, et elle n'exige ni force ni grandes mains.",
1:["Tenez la flûte à environ 45 degrés du corps.","Main gauche en haut — toujours ! C'est l'erreur la plus fréquente.","Posez le bout du bec sur la lèvre inférieure et refermez doucement les lèvres — sans mordre.","Soufflez doucement en murmurant « tou » — c'est le coup de langue qui commence chaque note."],
2:"Un souffle trop fort donnera un son strident et aigu. La flûte demande <b>très peu</b> d'air. Moins, c'est mieux.",
3:"La note si (B)",
4:"Première note : le pouce gauche bouche le trou arrière, l'index gauche le trou du haut. Voilà — c'est le si.",
5:{q:"Quelle main est toujours en haut sur la flûte à bec ?",o:["La droite","La gauche","Cela dépend si l'on est gaucher","Cela n'a pas d'importance"],w:"La main gauche est toujours en haut — sur tous les bois."},
6:"Jouez 10 si longs et stables, de 4 secondes chacun."}},

"recorder-2":{title:"Trois notes — si, la, sol",goal:"Jouer une courte mélodie",b:{
0:["<b>Si (B)</b> — pouce + doigt 1 de la main gauche.","<b>La (A)</b> — on ajoute le doigt 2 gauche.","<b>Sol (G)</b> — on ajoute le doigt 3 gauche."],
1:"Exercice à trois notes",
2:"Vérifiez que les doigts bouchent les trous <b>complètement</b> — avec la pulpe, pas le bout. Un trou à moitié ouvert donne un son criard.",
3:{q:"Que se passe-t-il si un trou n'est pas complètement bouché ?",o:["Le son est trop grave","Le son crie ou siffle","Il ne se passe rien","La flûte s'abîme"],w:"L'air qui fuit par un trou à moitié ouvert crée un sifflement."},
4:"Jouez l'exercice 5 fois sans aucun couac."}},

"recorder-3":{title:"Le premier morceau",goal:"Jouer une mélodie connue",b:{
0:"Mary Had a Little Lamb — mélodie populaire (domaine public)",
1:"Ce morceau utilise les notes déjà apprises, plus do et ré — on ajoute les doigts de la main droite.",
2:"Fredonnez d'abord la mélodie, et jouez-la ensuite sur l'instrument. Une oreille qui connaît la mélodie guide les doigts.",
3:{q:"Quelle étape est recommandée avant de jouer un nouveau morceau ?",o:["Le jouer vite","Le fredonner et se familiariser avec la mélodie","Lire les notes à voix haute","Accorder l'instrument"],w:"Une oreille qui connaît la mélodie repère immédiatement l'erreur."},
4:"Jouez le morceau en entier deux fois."}},

"recorder-4":{title:"Coup de langue et articulation",goal:"Séparer les notes proprement",b:{
0:"Sans coup de langue, toutes les notes se fondent en un seul son long. La langue, c'est la ponctuation de votre jeu.",
1:["<b>« Tou »</b> — un départ net pour chaque note.","<b>« Dou »</b> — un départ doux, pour les passages chantants.","<b>Legato</b> — coup de langue seulement sur la première note du groupe.","<b>Staccato</b> — notes courtes et séparées."],
2:"Staccato contre legato",
3:{q:"À quoi sert la langue quand on joue de la flûte à bec ?",o:["À garder un son aigu","À séparer et démarrer les notes proprement","À jouer plus fort","À accorder l'instrument"],w:"La langue définit le début de chaque note — sans elle, le jeu paraît brouillé."},
4:"Jouez une gamme complète une fois en staccato et une fois en legato."}},

"recorder-5":{title:"La gamme complète de do majeur",goal:"Jouer une octave entière",b:{
0:"Gamme de do majeur",
1:"Une gamme complète exige la coopération des deux mains. La difficulté principale : le passage des notes de la main gauche à celles de la main droite.",
2:"Travaillez uniquement le passage problématique (sol→fa) vingt fois, au lieu de rejouer toute la gamme encore et encore.",
3:{q:"Que vaut-il mieux faire face à un passage difficile ?",o:["Rejouer tout le passage sans arrêt","Isoler les deux notes problématiques et ne travailler qu'elles","Sauter le passage","Ralentir tout le morceau"],w:"Le travail ciblé est bien plus efficace que la répétition de l'ensemble."},
4:"Jouez la gamme aller-retour 5 fois au métronome à 60."}},

"recorder-6":{title:"La deuxième octave",goal:"Produire des notes aiguës avec le pouce",b:{
0:"Pour monter d'une octave, le pouce « pince » le trou arrière — en l'ouvrant à peine. C'est la technique de l'<b>octaviation</b>.",
1:["Faites glisser le pouce pour que l'ongle ouvre une petite fente.","Augmentez légèrement la pression d'air.","Jouez sol grave puis sol aigu en alternance."],
2:"Octaves",
3:"Son criard ? La fente est trop grande. Son grave ? La fente est fermée. La différence est d'un millimètre.",
4:{q:"Quel est le rôle du pouce gauche dans les notes aiguës ?",o:["Boucher complètement","Ouvrir une petite fente","Seulement tenir l'instrument","Ouvrir complètement"],w:"Une petite fente change le mode de vibration et monte le son d'une octave."},
5:"Jouez l'exercice d'octaves 10 fois."}},

"recorder-7":{title:"Dièses et bémols",goal:"Jouer les demi-tons",b:{
0:"À la flûte à bec, on obtient les demi-tons par des <b>doigtés fourchus</b> — en bouchant des trous non consécutifs.",
1:"Le fa dièse (F#) est la note la plus importante à apprendre : elle est nécessaire dans tout morceau en sol majeur.",
2:"Gamme de sol majeur (avec F#)",
3:{q:"Qu'est-ce qu'un doigté fourchu ?",o:["Boucher tous les trous","Boucher des trous non consécutifs pour créer un demi-ton","Ouvrir tous les trous","Un doigté à deux mains"],w:"Sauter un trou au milieu du doigté baisse la note d'un demi-ton."},
4:"Jouez la gamme de sol majeur aller-retour."}},

"recorder-8":{title:"Expression, respiration et phrasé",goal:"Jouer musicalement plutôt que mécaniquement",b:{
0:"La respiration n'est pas qu'un besoin physique — c'est une ponctuation. On respire à la fin d'une phrase musicale, pas au milieu d'un mot.",
1:["Marquez sur la partition où vous respirerez — avant de commencer à jouer.","Inspirez par la bouche, vite et sans bruit.","Ne respirez pas au milieu d'une note longue.","Terminez une phrase par un adoucissement délicat."],
2:"Jouez une phrase musicale comme si vous prononciez une phrase : un début, un sommet, une fin adoucie.",
3:{q:"Où faut-il respirer ?",o:["Tous les deux temps","À la fin d'une phrase musicale","Chaque fois qu'on manque d'air","Au milieu d'une note longue"],w:"Une respiration prévue en fin de phrase préserve la ligne musicale."},
4:"Jouez un morceau complet en marquant à l'avance trois points de respiration."}},

"recorder-9":{title:"Morceau final — Ode à la joie",goal:"Jouer une œuvre classique complète",b:{
0:"Ode à la joie — Beethoven (domaine public)",
1:"La flûte à bec est une excellente porte d'entrée vers d'autres instruments à vent : flûte traversière, clarinette, saxophone. La respiration et le coup de langue se transposent presque tels quels.",
2:{q:"Quel instrument est considéré comme la suite naturelle de la flûte à bec ?",o:["La batterie","La flûte traversière ou la clarinette","Le piano","Le violon"],w:"La technique de respiration et de coup de langue se transfère directement aux bois."},
3:"Jouez le morceau du début à la fin sans vous arrêter."}},

/* ===================== BATTERIE ===================== */
"drums-1":{title:"Le rythme — le langage corporel de la musique",goal:"Tenir une pulsation régulière",b:{
0:"Pas besoin d'une batterie pour commencer. Une table, deux mains ou deux crayons suffisent parfaitement pour les trois premières leçons.",
1:"Pulsations en noires — compter à quatre",
2:["Réglez le métronome sur 72.","Frappez dans les mains exactement sur chaque temps.","Comptez à voix haute : 1-2-3-4.","Accentuez le premier temps."],
3:"<b>Le test :</b> si vous précipitez ou traînez, vous entendez le métronome « bouger ». Si vous êtes précis, il disparaît presque sous votre frappe.",
4:{q:"Quel signe montre que vous êtes précis avec le métronome ?",o:["Le métronome sonne plus fort","Le métronome disparaît presque sous votre son","Vous jouez vite","Il n'y a aucun moyen de le savoir"],w:"Quand votre frappe tombe exactement sur le clic, les deux sons fusionnent."},
5:"Deux minutes de frappes précises à 72."}},

"drums-2":{title:"Le groove de base",goal:"Jouer le groove présent dans 80 % des morceaux",b:{
0:"Le groove de base a trois composantes : <b>charleston</b> (croches continues), <b>grosse caisse</b> (temps 1 et 3), <b>caisse claire</b> (temps 2 et 4).",
1:null,
2:["Commencez par le charleston seul : 1-et-2-et-3-et-4-et.","Ajoutez la grosse caisse sur les temps 1 et 3.","Ajoutez la caisse claire sur les temps 2 et 4.","Jouez les trois ensemble — lentement."],
3:"Si une main ou un pied « fait tomber » les autres, baissez la vitesse de 20 %. La vitesse est un résultat, pas un objectif.",
4:{q:"Sur quels temps tombe la caisse claire dans le groove de base ?",o:["1 et 3","2 et 4","Tous les temps","Seulement sur 1"],w:"La caisse claire sur 2 et 4, c'est le « backbeat » — le pouls du rock et de la pop."},
5:"Jouez le groove 16 mesures d'affilée à 70."}},

"drums-3":{title:"Indépendance des membres",goal:"Séparer les mains des pieds",b:{
0:"L'indépendance, c'est la capacité pour chaque membre de faire autre chose en même temps. Cela s'apprend — personne ne naît avec.",
1:["Jouez seulement charleston et caisse claire.","Seulement charleston et grosse caisse.","Seulement grosse caisse et caisse claire.","Combinez les trois.","Déplacez la grosse caisse sur le « 4-et » — et sentez le cerveau résister. C'est exactement l'entraînement."],
2:"Exercice d'indépendance",
3:"Travaillez l'indépendance 5 minutes par jour — mieux qu'une heure une fois par semaine. C'est de l'apprentissage moteur : il lui faut des répétitions espacées.",
4:{q:"Quelle est la façon efficace de développer l'indépendance ?",o:["Jouer vite","Décomposer en paires de membres et combiner progressivement","Jouer des morceaux entiers","Écouter de la musique"],w:"La décomposition en paires permet au cerveau de construire le motif petit à petit."},
5:"Travaillez trois paires de membres, une minute chacune."}},

"drums-4":{title:"Les breaks — la transition entre les parties",goal:"Jouer un break d'une mesure",b:{
0:"Un <b>break</b> est un court passage qui marque une transition entre les parties du morceau. Le break de base : quatre paires de croches sur caisse claire et toms.",
1:"Un break d'une mesure",
2:"La règle la plus importante d'un break : <b>revenir à temps</b>. Un break impressionnant qui arrive en retard est pire qu'un break simple qui tombe pile.",
3:{q:"Quel est le point le plus important dans un break ?",o:["Qu'il soit rapide","Qu'il se termine exactement à temps pour le temps 1","Qu'il soit long","Qu'il utilise tous les fûts"],w:"Le break sert le morceau — la précision du retour compte plus que le contenu."},
4:"Jouez 4 mesures de groove + une mesure de break, quatre fois."}},

"drums-5":{title:"Nuances et poids",goal:"Contrôler la force des frappes",b:{
0:"Un bon batteur ne frappe pas fort — il frappe <b>juste</b>. Un bon groove contient au moins trois niveaux de volume.",
1:["Charleston — doux et régulier.","Grosse caisse — moyenne, ressentie dans le ventre.","Caisse claire — forte et nette ; c'est ce qu'on entend.","Essayez de jouer le même groove à 30 % de volume puis à 90 %."],
2:"Le contrôle du volume vient de la prise : une tenue relâchée avec un « point d'appui » entre pouce et index donne une frappe libre et rebondissante.",
3:{q:"Quel élément du groove doit être le plus fort ?",o:["Le charleston","La caisse claire","Tout au même volume","La grosse caisse"],w:"La caisse claire est le « clic » du groove, elle ressort donc."},
4:"Jouez le groove à trois niveaux de volume différents."}},

"drums-6":{title:"Grooves dans différents styles",goal:"Connaître quatre grooves",b:{
0:"Rock",1:"Shuffle / blues",2:"Valse",3:"Funk (doubles croches)",
4:"Le style n'est pas seulement un motif — c'est aussi une sensation. Le shuffle balance, le rock est droit, le funk est net et haché.",
5:{q:"Qu'est-ce qui distingue les styles rythmiques entre eux ?",o:["Seulement la vitesse","Le motif de frappes et la sensation (droit ou balancé)","Le type de fûts","Le volume de jeu"],w:"Le motif et le « groove feeling » sont ce qui définit le style."},
6:"Jouez chacun des quatre grooves sur 8 mesures."}},

"drums-7":{title:"Lire la notation de batterie",goal:"Décoder un schéma de groove",b:{
0:"La notation de batterie utilise la même portée, mais chaque ligne représente un fût différent : charleston en haut (X), caisse claire au milieu, grosse caisse en bas.",
1:["Ligne du haut avec un X — charleston.","Le troisième interligne — caisse claire.","L'interligne du bas — grosse caisse.","Comptez la mesure : 1 et 2 et 3 et 4 et, et notez ce qui tombe où."],
2:{q:"Que signifie un X dans la notation de batterie ?",o:["Grosse caisse","Une cymbale ou le charleston","Caisse claire","Un silence"],w:"Une tête de note en forme de X indique un instrument métallique — charleston, crash ou ride."},
3:"Écrivez le groove de base sur papier en notation."}},

"drums-8":{title:"Jouer sur un morceau",goal:"Tenir le rythme avec de la musique",b:{
0:"Le batteur est l'horloge du groupe. Pour entrer : trouver le temps 1, compter une mesure entière, et entrer.",
1:["Écoutez le morceau et trouvez le backbeat (2 et 4).","Frappez dans les mains avec lui pendant 30 secondes.","Jouez le groove de base par-dessus le morceau.","Ajoutez un break toutes les 8 mesures."],
2:"Ne remplissez pas chaque seconde. Les silences du batteur comptent exactement autant que les frappes.",
3:{q:"Quel est le rôle central du batteur dans un groupe ?",o:["Être le plus fort","Tenir un rythme régulier et mener les transitions","Jouer des solos","Changer les accords"],w:"La stabilité du tempo est la fondation sur laquelle tout le groupe s'appuie."},
4:"Jouez sur un morceau que vous aimez pendant 3 minutes."}},

"drums-9":{title:"Bilan et coup d'œil vers la suite",goal:"Combiner groove, breaks et nuances",b:{
0:"Vous avez terminé les fondamentaux : groove, indépendance, breaks, nuances et styles.",
1:["Jouez 8 mesures de groove rock.","Un break d'une mesure.","8 mesures de shuffle.","Un break.","Terminez par un crash sur le temps 1."],
2:"L'étape suivante : les rudiments (paradiddle, ruff, roulement double) — ce sont les « gammes » du batteur.",
3:{q:"Que sont les rudiments ?",o:["Des types de fûts","Des motifs de frappes de base à partir desquels tout se construit","Des rythmes latins","Des types de baguettes"],w:"Les rudiments sont les briques de la technique de batterie."},
4:"Enregistrez-vous en jouant une séquence complète."}},

/* ===================== BASSE ===================== */
"bass-1":{title:"À la rencontre de la basse",goal:"Jouer les cordes à vide en rythme",b:{
0:"La basse est le pont entre la batterie et la guitare. Quatre cordes : <b>E-A-D-G</b>, une octave sous les quatre grosses cordes d'une guitare.",
1:"Les cordes à vide",
2:["Main droite : index et majeur alternent — la « technique à deux doigts ».","Le pouce repose sur le micro.","Main gauche : un doigt par case.","Jouez chaque corde à vide quatre fois."],
3:"<b>La première règle du bassiste :</b> une note propre et courte au bon endroit vaut plus que dix notes impressionnantes.",
4:{q:"Quel est l'accordage standard d'une basse quatre cordes ?",o:["G-C-E-A","E-A-D-G","E-A-D-G-B-E","D-A-D-G"],w:"E-A-D-G — les mêmes que les quatre grosses cordes d'une guitare, une octave plus bas."},
5:"Jouez 8 temps sur chaque corde à vide avec le métronome à 70."}},

"bass-2":{title:"Votre première ligne de basse",goal:"Jouer la fondamentale de chaque accord",b:{
0:"Le travail de base du bassiste : jouer la <b>fondamentale</b> de l'accord que joue la guitare, sur le premier temps de chaque mesure.",
1:"Ligne de basse pour la suite G-C-D",
2:["Accord G → jouez sol.","Accord C → jouez do.","Accord D → jouez ré.","Un temps long par mesure, puis quatre noires."],
3:"Un bon bassiste sait où se trouve chaque note sans réfléchir. Exercez-vous : « où est fa ? » et trouvez-le à trois endroits différents.",
4:{q:"Qu'est-ce que la fondamentale ?",o:["La note la plus aiguë de l'accord","La note qui donne son nom à l'accord","La première note de la gamme","La grosse corde"],w:"Pour un accord de G, la fondamentale est sol. C'est la note de base du bassiste."},
5:"Jouez les fondamentales de la suite G-C-D-G, quatre temps chacune."}},

"bass-3":{title:"Rythme et groove avec la batterie",goal:"Verrouiller la basse avec la grosse caisse",b:{
0:"La magie d'un groupe naît quand la basse et la grosse caisse jouent <b>exactement ensemble</b>. On appelle cela le « lock ».",
1:"Motif de grosse caisse pour s'entraîner",
2:["Écoutez le motif de grosse caisse.","Jouez une note exactement sur chaque frappe.","N'ajoutez pas de notes — soyez seulement précis.","Ajoutez maintenant une note de passage avant la mesure suivante."],
3:"Si vous jouez entre les temps sans être sûr — ne jouez pas. Un silence précis vaut mieux qu'une note imprécise.",
4:{q:"Avec quel instrument la basse doit-elle être la plus synchronisée ?",o:["La guitare","La grosse caisse","Le chant","Le piano"],w:"Le duo basse + grosse caisse est la base rythmique de tout groupe."},
5:"Jouez sur le motif de grosse caisse pendant deux minutes."}},

"bass-4":{title:"Les notes sur le manche",goal:"Trouver chaque note à deux endroits",b:{
0:"Sur la corde mi : case 1 = fa, case 3 = sol, case 5 = la. Sur la corde la : case 2 = si, case 3 = do.",
1:"<b>La règle de l'octave :</b> la même note se trouve aussi deux cordes plus bas et deux cases plus loin. C'est le raccourci le plus utile à la basse.",
2:"La même note à deux octaves",
3:{q:"Où se trouve l'octave d'une note à la basse ?",o:["Sur la même corde, 12 cases plus haut, ou deux cordes plus bas et deux cases plus loin","Sur la même case de la corde voisine","Il n'y a pas de règle fixe","Trois cases en arrière"],w:"Les deux réponses sont justes, et le motif « deux et deux » est le plus rapide à utiliser."},
4:"Choisissez une note et trouvez-la à trois endroits différents du manche."}},

"bass-5":{title:"La walking bass",goal:"Relier les accords par des notes de passage",b:{
0:"<b>Walking bass</b> — une ligne de basse qui joue quatre notes par mesure et relie les accords pas à pas.",
1:"Une walking line simple",
2:["Commencez sur la fondamentale.","Jouez des notes de l'accord (fondamentale, tierce, quinte).","Atteignez une note située à un pas de la fondamentale suivante.","Posez-vous sur la fondamentale suivante au temps 1."],
3:{q:"À quoi sert une note de passage dans une walking bass ?",o:["À remplir l'espace","À conduire en douceur vers la fondamentale de l'accord suivant","À sonner rapide","À remplacer la batterie"],w:"Une note de passage crée une attente et une attraction naturelle vers l'accord suivant."},
4:"Jouez une walking line sur la suite C-F-G-C."}},

"bass-6":{title:"Techniques de main droite",goal:"Découvrir les doigts, le médiator et le slap",b:{
0:["<b>Aux doigts :</b> le son le plus chaud et le plus courant.","<b>Au médiator :</b> un son net et tranchant, adapté au rock et au punk.","<b>Slap :</b> le pouce frappe la grosse corde, le doigt « claque » la fine — le son funk caractéristique."],
1:"Motif de slap de base",
2:"En slap, le pouce tourne autour d'un axe — il ne « pique » pas. Le rebond fait partie du mouvement.",
3:{q:"Qu'est-ce que la technique du slap ?",o:["Jouer au médiator","Une frappe du pouce et un claqué du doigt","Jouer à deux mains","Étouffer les cordes"],w:"La combinaison frappe du pouce / claqué du doigt crée le son percussif."},
4:"Jouez huit mesures avec chacune des techniques."}},

"bass-7":{title:"Étouffement et contrôle du bruit",goal:"Jouer proprement sans cordes qui résonnent",b:{
0:"Le problème numéro un à la basse n'est pas les fausses notes — c'est le <b>bruit</b> : des cordes qui continuent de vibrer.",
1:["Le pouce de la main droite repose sur la grosse corde et l'étouffe.","Les doigts de la main gauche qui ne jouent pas effleurent les cordes voisines.","Après chaque note, pensez à la façon dont vous l'<b>arrêtez</b>, pas seulement dont vous la commencez.","Jouez une note, étouffez-la complètement, et seulement ensuite jouez la suivante."],
2:{q:"Quel est le problème le plus fréquent dans le jeu de basse ?",o:["Les fausses notes","Le bruit des cordes non étouffées","Le tempo lent","Les cordes fines"],w:"Le contrôle du bruit fait la différence entre un amateur et un professionnel."},
3:"Jouez note-silence-note-silence pendant une minute."}},

"bass-8":{title:"Une ligne de basse pour un morceau entier",goal:"Construire une ligne de basse autonome",b:{
0:"Une bonne ligne de basse se construit en trois étapes : fondamentales seules → fondamentales en rythme → ajout de notes de passage et de variations.",
1:"Riff de blues (exercice original)",
2:"Écoutez les bassistes des morceaux que vous aimez. Remarquez à quel point ils jouent peu — et à quel point cela sonne juste.",
3:{q:"Quel est le bon ordre pour construire une ligne de basse ?",o:["Improviser tout de suite","Fondamentales → rythme → notes de passage","Copier un solo","Commencer par la note la plus aiguë"],w:"La construction progressive garde la ligne stable et au service du morceau."},
4:"Construisez une ligne de basse pour un morceau que vous connaissez, en trois étapes."}},

"bass-9":{title:"Bilan et coup d'œil vers la suite",goal:"Jouer avec un groupe",b:{
0:"Vous avez terminé les fondamentaux. Un bassiste au tempo stable, au son propre et à la compréhension harmonique est recherché dans tous les groupes.",
1:["Travaillez au métronome chaque jour, même 5 minutes.","Enregistrez-vous — l'oreille repère ce que la main ne sent pas.","Jouez avec d'autres dès que possible.","Apprenez la gamme majeure et le mineur naturel sur tout le manche."],
2:{q:"Quelle est la qualité la plus importante chez un bassiste ?",o:["La vitesse","Un tempo stable et un son propre","La connaissance du solfège","Un matériel coûteux"],w:"C'est la stabilité qui fait sonner tout le groupe."},
3:"Jouez un morceau complet du début à la fin avec un métronome."}}

});

/* ---- les quatre nouveaux instruments ---- */
I18N.registerLessons("fr", {

"violin-1":{title:"Tenue et cordes à vide",goal:"Produire un son net sur les quatre cordes",b:{
0:"Le violon est l'instrument où <b>l'oreille guide le doigt</b>. Il n'y a pas de frettes, donc chaque note se construit en écoutant — et c'est précisément ce qui en fait le meilleur professeur pour l'oreille.",
1:"Quatre cordes, de la plus grosse à la plus fine : <b>sol, ré, la, mi</b>. L'intervalle entre chaque paire est une quinte.",
3:["Posez le violon sur la clavicule, la mâchoire sur la mentonnière.","La main gauche tient le manche légèrement — elle ne serre pas.","L'archet se pose sur la corde à mi-chemin entre le chevalet et la touche.","Tirez l'archet lentement, avec une pression régulière. Un son net vaut mieux qu'un son fort."],
4:"Un sifflement ? Trois causes possibles : pression inégale, archet trop loin du chevalet, ou vitesse changeante. Ralentissez.",
5:{q:"Comment les cordes du violon sont-elles accordées ?",o:["En quartes","En quintes","En octaves","En tierces"],w:"Sol-ré-la-mi — une quinte entre chaque paire de cordes voisines."},
6:"Jouez chaque corde à vide huit fois avec un archet complet, sans sifflement."}},

"violin-2":{title:"Le premier doigt",goal:"Jouer quatre notes nouvelles",b:{
0:"Le premier doigt se pose à <b>un ton entier</b> de la corde à vide. C'est le point d'ancrage de toute la main.",
2:"Collez un petit morceau de ruban à l'endroit du premier doigt. Ce n'est pas tricher — c'est ainsi que tous les violonistes du monde apprennent la première année.",
3:"Corde à vide et premier doigt",
4:{q:"Quelle est la distance entre la corde à vide et le premier doigt ?",o:["Un demi-ton","Un ton entier","Un ton et demi","Deux tons"],w:"Un ton entier — et c'est la première distance que l'oreille apprend."},
5:"Jouez l'exercice lentement et vérifiez chaque note avec l'accordeur de l'application."}},

"violin-3":{title:"Une première mélodie",goal:"Jouer un morceau entier sur deux cordes",b:{
0:"Avec les cordes à vide et le premier doigt, vous pouvez déjà jouer une vraie mélodie.",
2:"Exercice sur deux cordes",
3:"<b>La règle de la première année :</b> lent et net l'emporte toujours sur rapide et brouillon.",
4:{q:"Qu'est-ce qui compte le plus à ce stade ?",o:["Jouer vite pour progresser","Jouer lentement et écouter chaque note","Sauter les notes difficiles","Jouer le plus fort possible"],w:"Au violon, la moindre imprécision s'entend aussitôt. Ralentir est le raccourci."},
5:"Jouez la mélodie cinq fois, un peu plus vite à chaque fois."}},

"violin-4":{title:"Trois doigts — votre première gamme",goal:"Jouer la gamme de ré majeur sur deux cordes",b:{
0:"Au violon, la gamme ne se construit pas à partir de frettes mais d'un <b>schéma de doigts fixe</b>. Une fois que la main l'a appris, il se répète sur chaque corde.",
1:"Sur la corde de ré : doigt 1 = mi, doigt 2 = fa dièse, doigt 3 = sol. Remarquez que les doigts 2 et 3 <b>se touchent</b> — c'est le signe que le schéma est juste.",
3:"Gamme de ré majeur",
4:"Les doigts 2 et 3 sont collés dans une gamme majeure. Si un écart s'ouvre entre eux, le fa dièse sortira trop bas.",
5:{q:"Qu'est-ce qui caractérise la position des doigts 2 et 3 en majeur ?",o:["Un large écart entre eux","Ils se touchent","Le doigt 3 n'est pas utilisé","Il n'y a pas de règle fixe"],w:"Leur proximité est le demi-ton entre le troisième et le quatrième degré."},
6:"Jouez la gamme dans les deux sens dix fois, lentement, en vérifiant chaque note à l'accordeur."}},

"violin-5":{title:"La distribution de l'archet",goal:"Maîtriser la durée et la force du son",b:{
0:"L'archet est la <b>respiration</b> du violon. Une note longue demande un archet lent, une note courte peu d'archet — et la pression reste constante.",
1:["Repérez trois zones : le talon, le milieu, la pointe.","Jouez une ronde avec l'archet entier, du talon à la pointe, en quatre secondes.","Jouez quatre noires dans ce même archet — chacune un quart de la longueur.","Maintenant jouez des croches uniquement au milieu de l'archet."],
2:"Distribution de l'archet",
3:"Le son faiblit en fin d'archet ? La pression descend avec votre bras. Gardez-la régulière jusqu'à la pointe.",
4:{q:"Qu'est-ce qui détermine la durée d'une note au violon ?",o:["La pression du doigt","La vitesse de l'archet","La tenue de l'instrument","L'épaisseur de la corde"],w:"La vitesse de l'archet donne la durée ; la pression donne le volume."},
5:"Jouez une gamme entière avec un archet complet par note, puis avec un demi-archet."}},

"violin-6":{title:"Deuxième corde et changements",goal:"Passer d'une corde à l'autre sans bruit",b:{
0:"Le passage entre cordes est l'endroit où s'entend la différence entre un débutant et un musicien. Le secret : <b>le bras commence à bouger avant que la note ne change</b>.",
2:"Exercice de changements",
3:"Si un son double se fait entendre pendant le passage, l'archet a touché deux cordes. C'est l'angle qui doit changer, pas la pression.",
4:{q:"Qu'est-ce qui provoque un son double lors d'un changement de corde ?",o:["Une pression trop forte","L'archet touche deux cordes","L'instrument est désaccordé","Le doigt est mal placé"],w:"C'est l'angle de l'archet qui sépare les cordes."},
5:"Jouez l'exercice dix fois, parfaitement net."}},

"violin-7":{title:"Un premier vibrato",goal:"Découvrir le mouvement du vibrato",b:{
0:"Le vibrato est un <b>petit balancement du doigt</b> qui réchauffe le son. On l'enseigne plus tard qu'on ne le croit — et c'est volontaire : il masque l'imprécision, on apprend donc d'abord à jouer net sans lui.",
1:["Posez le doigt 2 sur la corde de la, sans archet.","Balancez la main d'avant en arrière depuis le poignet, pas depuis le doigt.","Le doigt reste en place — seule la hauteur varie légèrement.","N'ajoutez l'archet que lorsque le mouvement est fluide."],
2:"Un vibrato rapide et étroit ressemble à un tremblement. Lent et large, il ressemble à un chant. Commencez lentement.",
3:{q:"D'où vient le mouvement du vibrato ?",o:["Du doigt","Du poignet","Du coude seulement","De l'épaule"],w:"Le mouvement vient du poignet ; le doigt ne fait que l'accompagner."},
4:"Travaillez le mouvement une minute sans archet, puis une minute avec."}},

"violin-8":{title:"Une mélodie complète",goal:"Jouer un air connu du début à la fin",b:{
0:"Tout se réunit maintenant : le schéma de doigts, la distribution de l'archet et les changements de corde.",
1:"Mélodie pour deux cordes",
2:"Jouez d'abord sans archet — en pizzicato — pour vérifier que les doigts sont en place. Ajoutez l'archet ensuite.",
3:{q:"Que vaut-il mieux vérifier avant d'ajouter l'archet ?",o:["Le volume","Que les doigts sont bien placés","Le tempo","La position de la tête"],w:"Le pizzicato isole la main gauche et révèle aussitôt les imprécisions."},
4:"Jouez la mélodie cinq fois — deux fois en pizzicato et trois fois à l'archet."}},

"violin-9":{title:"Bilan et suite",goal:"Jouer avec assurance et savoir où aller",b:{
0:"Vous avez terminé les bases : la tenue, les cordes à vide, le schéma de doigts, la distribution de l'archet et les changements. Tout le reste se construit là-dessus.",
1:"La suite : <b>la deuxième position</b> (déplacer toute la main sur le manche), <b>jouer sur deux cordes à la fois</b>, et <b>lire la musique</b> en jouant.",
2:"Morceau final",
3:"<b>L'erreur classique de deuxième année :</b> accélérer avant que le son ne soit net. Jouez tout au métronome lent — et vous dépasserez ceux qui se sont pressés.",
4:{q:"Quelle est la suite naturelle au violon ?",o:["Jouer plus vite","La deuxième position et la lecture","Changer d'instrument","Abandonner l'archet"],w:"La deuxième position ouvre le reste du manche, et la lecture ouvre le répertoire."},
5:"Jouez le morceau final et enregistrez-vous. Se réécouter est le professeur le plus honnête."}},

"harmonica-1":{title:"Souffler et aspirer",goal:"Produire un son net depuis un seul trou",b:{
0:"L'harmonica est le seul instrument où <b>souffler et aspirer produisent tous deux un son</b> — et deux sons différents depuis le même trou.",
1:"Un harmonica en do a dix trous et vingt anches. Le quatrième trou est le point de départ de presque toutes les mélodies.",
3:["Tenez l'harmonica entre le pouce et l'index, les chiffres vers le haut.","Arrondissez les lèvres comme pour dire « ou ».","Soufflez doucement dans le trou quatre — c'est do.","Maintenant aspirez depuis le même trou — c'est ré."],
4:"Plusieurs notes sortent en même temps ? Votre bouche est trop ouverte. Resserrez les lèvres jusqu'à ce qu'il ne reste qu'une note nette.",
5:{q:"Qu'est-ce qui distingue l'harmonica des autres instruments à vent ?",o:["Il n'a pas de notes aiguës","Souffler et aspirer produisent tous deux un son","Il faut le réaccorder chaque fois","Il faut appuyer sur des boutons"],w:"Chaque trou contient deux anches — une pour souffler, une pour aspirer."},
6:"Alternez souffle et aspiration sur le trou 4, vingt fois, avec un son net."}},

"harmonica-2":{title:"Quatre trous — votre première mélodie",goal:"Jouer une mélodie connue",b:{
0:"Les trous 4 à 7 contiennent une gamme complète de do majeur. Presque toutes les chansons populaires y vivent.",
2:"Regardez la flèche au-dessus du schéma : vers le haut, on souffle ; vers le bas, on aspire. C'est tout ce qu'il faut retenir.",
3:"La gamme à l'harmonica",
4:{q:"Dans quels trous se trouve une gamme complète de do majeur ?",o:["De 1 à 4","De 4 à 7","De 7 à 10","Dans tous"],w:"Seuls les trous 4 à 7 donnent la gamme complète sans bend."},
5:"Jouez la gamme dans les deux sens dix fois."}},

"harmonica-3":{title:"Votre première chanson",goal:"Jouer une mélodie entière de mémoire",b:{
0:"Maintenant on assemble tout. Cette mélodie n'utilise que les trous 4 à 6.",
2:"Mélodie pour quatre trous",
3:"Essayez de jouer sans regarder les chiffres. À l'harmonica, l'oreille trouve le trou plus vite que l'œil.",
4:{q:"Quelle est la meilleure façon d'apprendre une mélodie à l'harmonica ?",o:["Mémoriser les numéros de trous","Écouter et chercher à l'oreille","Compter les respirations","Lire la partition"],w:"L'harmonica a été conçu pour jouer d'oreille — c'est sa force."},
5:"Jouez la mélodie trois fois les yeux fermés."}},

"harmonica-4":{title:"Jouer un seul trou",goal:"Produire une note nette sans voisines",b:{
0:"Jusqu'ici plusieurs notes se faisaient peut-être entendre ensemble. Vous allez apprendre à n'en sortir <b>qu'une seule</b> — et c'est ce qui transforme le bruit en mélodie.",
1:["Enfoncez l'harmonica plus profondément entre les lèvres, comme si vous buviez.","La langue repose en bas, détendue.","Resserrez l'ouverture des lèvres jusqu'à ce qu'une seule note sonne.","Vérifiez : soufflez dans le trou 4 — si vous entendez un accord, vos lèvres sont trop larges."],
3:"Deuxième méthode, le <b>blocage de langue</b> : couvrez trois trous avec la bouche et bloquez-en deux avec la langue. Il en reste un d'ouvert.",
4:{q:"Pourquoi plusieurs notes sonnent-elles ensemble ?",o:["L'harmonica est cassé","L'ouverture des lèvres est trop large","Vous soufflez trop fort","Les trous sont bouchés"],w:"Une bouche large couvre plusieurs trous à la fois."},
5:"Jouez les trous 4, 5 et 6 en soufflant — chacun séparément et proprement, vingt fois."}},

"harmonica-5":{title:"La deuxième octave",goal:"Étendre la tessiture aux trous 1 à 7",b:{
0:"Les trous graves (1–3) donnent les sons profonds, les aigus (7–10) les sons perçants. La plupart des mélodies vivent au milieu.",
2:"Notez une curiosité : à partir du trou 7, <b>l'aspiration est plus grave que le souffle</b> — l'inverse des trous graves. C'est une propriété de l'accord, pas une panne.",
3:"Tessiture complète",
4:{q:"Qu'est-ce qui change à partir du trou 7 ?",o:["Rien","L'aspiration devient plus grave que le souffle","On ne peut plus aspirer","Le son est plus faible"],w:"C'est une inversion intégrée à l'accord Richter."},
5:"Jouez tous les souffles du trou 1 au trou 10 et retour."}},

"harmonica-6":{title:"Rythme et respiration",goal:"Jouer en mesure sans manquer d'air",b:{
0:"À l'harmonica, la respiration est à la fois le son et le carburant. Jouez trop longtemps dans un sens et vous manquerez d'air.",
1:"Alternance souffle et aspiration",
2:"<b>La règle :</b> si la mélodie demande trois souffles d'affilée, cherchez un endroit pour changer de sens. On retrouve souvent la même note dans un autre trou.",
3:"Exercice de respiration",
4:{q:"Que faire quand l'air manque au milieu d'une phrase ?",o:["Souffler plus fort","Chercher un endroit pour changer de sens","Arrêter de jouer","Jouer plus vite"],w:"Changer de sens, c'est la respiration de l'harmonica."},
5:"Jouez l'exercice deux minutes d'affilée sans être essoufflé."}},

"harmonica-7":{title:"Accords et trémolo",goal:"Utiliser plusieurs trous ensemble volontairement",b:{
0:"Jusqu'ici nous luttions contre les notes voisines. Maintenant on les <b>utilise volontairement</b> : plusieurs trous ensemble donnent un accord complet.",
1:"Souffler dans les trous 1–4 donne un accord de do majeur. Aspirer dans les trous 1–4 donne un accord de sol.",
2:"<b>Trémolo :</b> agitez la main qui tient l'harmonica devant votre bouche. Le son ondule et évoque un train.",
3:"Accompagnement en accords",
4:{q:"Quel accord donne un souffle dans les trous 1 à 4 ?",o:["Sol majeur","Do majeur","La mineur","Ré majeur"],w:"Les souffles sont bâtis sur les notes de l'accord de do — do, mi, sol."},
5:"Jouez un accompagnement en accords sur une chanson que vous connaissez, deux minutes."}},

"harmonica-8":{title:"Une chanson entière",goal:"Jouer une mélodie connue du début à la fin",b:{
0:"Maintenant on assemble : trou unique, rythme et respiration planifiée.",
2:"Mélodie complète",
3:"Repérez à l'avance où vous soufflez et où vous aspirez. Planifier évite l'essoufflement.",
4:{q:"Qu'est-ce qui aide à ne pas s'essouffler ?",o:["Jouer doucement","Planifier à l'avance souffles et aspirations","Jouer vite","Raccourcir la chanson"],w:"Planifier le sens de l'air est la compétence centrale de l'harmonica."},
5:"Jouez la mélodie cinq fois de suite sans vous arrêter."}},

"harmonica-9":{title:"Bilan et suite",goal:"Savoir ce que vous avez appris et où aller",b:{
0:"Vous avez terminé les bases : souffle et aspiration, trou unique, tessiture complète, rythme, accords et une chanson entière.",
1:"La suite : le <b>bend</b> — modifier la hauteur du son avec la langue, ce qui permet de jouer les notes absentes de l'accord. C'est ce qui donne à l'harmonica sa couleur blues.",
2:"Morceau final",
3:"Le bend demande des mois, pas des jours. Ne vous y attaquez pas avant que vos notes simples soient parfaitement nettes.",
4:{q:"Qu'est-ce qui rend le bend possible ?",o:["Un autre harmonica","Changer la forme de la bouche et de la langue","Souffler fort","Remplacer les anches"],w:"La forme de la cavité buccale modifie la hauteur du son."},
5:"Jouez le morceau final et enregistrez-vous."}},

"glock-1":{title:"Une première frappe",goal:"Produire un son net et comprendre la disposition",b:{
0:"Le glockenspiel est l'instrument mélodique le plus facile pour commencer : <b>rien à accorder, pas de doigté et pas de souffle</b>. On frappe — et la bonne note sort.",
1:"Les lames sont disposées exactement comme les touches d'un piano : une longue rangée de blanches, et au-dessus des groupes de deux et de trois.",
2:"Frappez la lame marquée — c'est do",
3:["Tenez la mailloche souplement, entre le pouce et l'index.","Frappez au centre de la lame — pas à son extrémité.","Relevez la mailloche aussitôt après la frappe. Une mailloche qui reste posée étouffe le son.","Une frappe légère suffit. L'instrument fait le travail."],
4:"Un son mat ? La mailloche reste sur la lame. Pensez rebond, pas pression.",
5:{q:"Où frappe-t-on la lame ?",o:["À l'extrémité","Au centre","Près de la vis","Peu importe"],w:"Le centre donne le son le plus plein. Les extrémités sonnent mat."},
6:"Frappez chaque lame blanche une fois, du grave à l'aigu, avec un son net."}},

"glock-2":{title:"La gamme et votre première mélodie",goal:"Jouer une mélodie connue",b:{
0:"La gamme de do majeur, ce sont simplement toutes les lames blanches à la suite. C'est tout ce qu'il faut pour la première mélodie.",
1:"Gamme de do majeur",
2:"Première mélodie",
3:"<b>Alterner les mains :</b> droite-gauche-droite-gauche. Cela double la vitesse sans effort supplémentaire.",
4:{q:"Quel est l'avantage d'alterner les mains ?",o:["Un son plus fort","On joue plus vite sans effort","Les lames s'usent moins","Aucun avantage"],w:"Une seule main doit revenir ; deux mains alternent sans interruption."},
5:"Jouez la mélodie en alternant les mains, cinq fois."}},

"glock-3":{title:"Rythme et nuances",goal:"Jouer à différentes intensités et en mesure",b:{
0:"Au glockenspiel le son est court, donc <b>le temps et l'intensité</b> sont toute l'expression dont vous disposez. C'est ce qui transforme un jeu banal en jeu marquant.",
1:"Rythme de base",
2:"Essayez de jouer la même mélodie une fois fort et une fois doucement. La différence est plus grande qu'il n'y paraît.",
3:"La même mélodie, un autre rythme",
4:{q:"Qu'est-ce qui crée l'expression au glockenspiel ?",o:["La durée des notes","L'intensité et le temps","L'accord des lames","Le nombre de mailloches"],w:"Le son est court et fixe : vos outils sont le volume et le placement."},
5:"Jouez la mélodie trois fois : doucement, moyennement et fort."}},

"glock-4":{title:"Deux mains et déplacements",goal:"Jouer un passage qui se déplace entre les registres",b:{
0:"Au glockenspiel la main ne reste pas en place. <b>L'œil guide — la main suit</b>, et cela s'apprend séparément.",
1:"Trois points de repère — do, sol et do aigu",
2:["Repérez les trois points d'ancrage sur l'instrument.","Frappez do puis sol, sans regarder la mailloche.","Ajoutez le do aigu.","Jouez maintenant les trois à la suite au métronome 60."],
3:"Regardez la lame <b>suivante</b> pendant que vous frappez l'actuelle. C'est le secret de tout percussionniste à claviers.",
4:{q:"Où regarder pendant qu'on joue ?",o:["La mailloche","La lame suivante","Uniquement la partition","Peu importe"],w:"Le regard précède la main, exactement comme en lecture."},
5:"Jouez do-sol-do vingt fois sans manquer."}},

"glock-5":{title:"Les lames supérieures",goal:"Jouer dans une gamme avec un dièse",b:{
0:"Les lames supérieures sont les demi-tons — exactement comme les touches noires du piano, et dans les mêmes groupes de deux et de trois.",
1:"Gamme de sol majeur — attention au fa dièse",
2:"Les lames supérieures sont plus étroites. Visez le centre, sinon la mailloche glisse.",
3:{q:"Comment sont disposées les lames supérieures ?",o:["En rangée régulière","En groupes de deux et de trois","Au hasard","Il n'y a pas de lames supérieures"],w:"Exactement comme les touches noires d'un piano."},
4:"Jouez la gamme de sol majeur dans les deux sens, cinq fois."}},

"glock-6":{title:"Un rythme plus complexe",goal:"Jouer des croches et des notes pointées",b:{
0:"Le son du glockenspiel est court, donc <b>la précision rythmique</b> s'entend aussitôt. Ici on apprend à diviser le temps.",
1:"Croches",
2:"Mélodie en croches",
3:"Comptez à voix haute : « un-et-deux-et ». Compter à voix haute est plus précis que compter dans sa tête.",
4:{q:"Qu'est-ce qui aide à la précision rythmique ?",o:["Jouer fort","Compter à voix haute","Jouer vite","Regarder ses mains"],w:"Compter à voix haute relie le corps au temps."},
5:"Jouez la mélodie au métronome 70, puis à 85."}},

"glock-7":{title:"Deux voix",goal:"Jouer une mélodie et un accompagnement ensemble",b:{
0:"Deux mains, deux voix. Une main joue la mélodie, l'autre ajoute une note d'ancrage.",
1:"Accord de do — les trois notes ensemble",
2:"Mélodie avec ancrage",
3:"Commencez avec la seconde main qui ne frappe que sur le premier temps de chaque mesure. C'est déjà assez pour que cela sonne plein.",
4:{q:"Quelle est la façon la plus simple d'ajouter une deuxième voix ?",o:["Tout jouer deux fois","Une note d'ancrage sur le premier temps","Jouer plus vite","Ajouter une troisième mailloche"],w:"Un seul ancrage par mesure crée déjà la sensation d'accompagnement."},
5:"Jouez la mélodie avec ancrage, cinq fois."}},

"glock-8":{title:"Un morceau à interpréter",goal:"Jouer une pièce complète avec assurance",b:{
0:"Maintenant tout se combine : déplacements, lames supérieures, rythme et deux voix.",
1:"Morceau à interpréter",
2:"Travaillez la pièce en trois sections séparées, et ne les reliez qu'ensuite. C'est ainsi que travaillent les professionnels.",
3:{q:"Comment apprend-on une pièce longue ?",o:["En la rejouant encore et encore","En la découpant en sections puis en les reliant","En ne jouant que le début","En accélérant progressivement"],w:"Le découpage fait gagner du temps et empêche les erreurs de s'installer."},
4:"Jouez la pièce trois fois de suite sans vous arrêter."}},

"glock-9":{title:"Bilan et suite",goal:"Savoir ce que vous avez appris et où aller",b:{
0:"Vous avez terminé : la frappe nette, la gamme, les déplacements, les lames supérieures, le rythme et les deux voix.",
1:"La suite : le <b>xylophone et le marimba</b> (lames de bois, son plus chaud), <b>quatre mailloches</b> dans deux mains, et <b>la lecture</b> en jouant.",
2:"Morceau final",
3:"Le glockenspiel est une excellente porte d'entrée vers toutes les percussions mélodiques. La compétence se transfère presque intégralement.",
4:{q:"Quelle est la différence entre un glockenspiel et un xylophone ?",o:["La taille","Lames de métal contre lames de bois","Le nombre de lames","L'accord"],w:"Le métal donne un son clair et long ; le bois, chaud et court."},
5:"Jouez le morceau final et enregistrez-vous."}},

"mandolin-1":{title:"Découverte et cordes à vide",goal:"Produire un son net et comprendre l'accord",b:{
0:"La mandoline est accordée <b>exactement comme un violon</b> — sol, ré, la, mi — mais elle a des frettes. Chaque note a une place fixe, et rien n'est à chercher à l'oreille.",
2:["Tenez le médiator entre le pouce et l'index, par la pointe seulement.","Jouez alternativement vers le bas et vers le haut — c'est le mouvement de base.","Main gauche : appuyez juste derrière la frette, pas dessus.","Jouez chaque paire de cordes à vide quatre fois."],
3:"Chaque note a deux cordes côte à côte. C'est ce qui donne à la mandoline sa sonorité claire.",
4:{q:"En quoi la mandoline diffère-t-elle du violon ?",o:["Par son accord","Par la présence de frettes","Par le nombre de cordes","Par la taille seulement"],w:"L'accord est identique ; les frettes font la différence, et c'est ce qui facilite les débuts."},
5:"Jouez chaque corde à vide huit fois, vers le bas et vers le haut."}},

"mandolin-2":{title:"Premières notes sur le manche",goal:"Jouer votre première gamme",b:{
0:"Grâce aux frettes, trouver une note à la mandoline est affaire de comptage — pas d'écoute.",
2:"Cinq notes",
3:"Un doigt par frette — c'est la règle qui vous épargne des années de corrections.",
4:{q:"Comment trouve-t-on une note à la mandoline ?",o:["À l'oreille seulement","Par le numéro de frette","À la couleur de la corde","On ne peut pas en être sûr"],w:"Les frettes fixent la hauteur avec précision."},
5:"Jouez les cinq notes dans les deux sens, dix fois."}},

"mandolin-3":{title:"Une première mélodie",goal:"Jouer un morceau entier",b:{
0:"Maintenant on assemble : cordes à vide, notes sur le manche et médiator régulier.",
2:"Mélodie pour mandoline",
3:"<b>Trémolo :</b> répétition rapide du médiator sur la même note. C'est la sonorité que tout le monde reconnaît — mais seulement une fois le jeu ordinaire bien stable.",
4:{q:"Qu'est-ce que le trémolo ?",o:["Un changement d'accord rapide","Une répétition rapide du médiator sur la même note","Jouer sur deux cordes","Ralentir à la fin"],w:"C'est la technique emblématique de la mandoline."},
5:"Jouez la mélodie cinq fois avec un médiator régulier."}},

"mandolin-4":{title:"Votre premier accord",goal:"Jouer un accord de sol et y enchaîner",b:{
0:"À la mandoline, un accord ne demande le plus souvent que <b>deux doigts</b> — bien moins qu'à la guitare.",
2:["Doigt 1 sur la corde de la, frette 2.","Doigt 2 sur la corde de mi, frette 3.","Les deux autres cordes restent à vide.","Jouez vers le bas sur les quatre paires."],
3:"Appuyez juste derrière la frette, pas dessus. C'est là qu'il faut le moins de force.",
4:{q:"Combien de doigts faut-il pour un accord de base à la mandoline ?",o:["Quatre","Deux","Trois","Aucun"],w:"Deux suffisent pour la plupart des accords ouverts."},
5:"Alternez entre l'accord de sol et les cordes à vide, vingt fois."}},

"mandolin-5":{title:"Deux accords et une chanson",goal:"Accompagner une chanson entière avec deux accords",b:{
0:"Avec deux accords on peut déjà accompagner des centaines de chansons. Le passage de l'un à l'autre, c'est tout le travail.",
1:"Jeu bas-haut",
2:"<b>La règle du changement :</b> levez les doigts un instant avant le temps, pas dessus. Ainsi il n'y a pas de trou dans le rythme.",
3:"Exercice d'accompagnement",
4:{q:"Quand lève-t-on les doigts lors d'un changement d'accord ?",o:["Exactement sur le temps","Un instant avant le temps","Après le temps","Peu importe"],w:"Lever tôt préserve la continuité du rythme."},
5:"Alternez les deux accords pendant deux minutes sans vous arrêter."}},

"mandolin-6":{title:"Le trémolo",goal:"Produire un son tenu par répétition du médiator",b:{
0:"La mandoline n'a pas de son long — il s'éteint aussitôt. Le <b>trémolo</b> est la solution : une répétition rapide qui crée l'illusion d'un son tenu.",
1:["Tenez le médiator très souplement — c'est la clé.","Bougez depuis le poignet, pas depuis le coude.","Commencez lentement et régulièrement, et n'accélérez qu'ensuite.","Jouez une note en trémolo pendant quatre secondes."],
2:"Une prise crispée donne un trémolo saccadé. Plus la prise est souple, plus le son est lisse.",
3:"Note longue en trémolo",
4:{q:"Qu'est-ce qui compte le plus dans le trémolo ?",o:["La vitesse","Une prise détendue","Une forte pression","Un médiator épais"],w:"La détente permet la vitesse ; la tension l'empêche."},
5:"Travaillez le trémolo sur une seule note, une minute par corde."}},

"mandolin-7":{title:"Gammes sur deux octaves",goal:"Étendre la tessiture le long du manche",b:{
0:"Grâce à l'accord en quintes, le même schéma de doigts se répète sur chaque paire de cordes. On l'apprend une fois — et on le joue partout.",
2:"Gamme de sol sur deux octaves",
3:"Le schéma appris sur la corde de sol fonctionne exactement pareil sur celle de ré. C'est la grande économie de l'accord en quintes.",
4:{q:"Quel est l'avantage d'un accord en quintes ?",o:["Un son plus fort","Le même schéma se répète sur chaque paire de cordes","C'est plus facile à accorder","Moins de cordes"],w:"Le schéma est conservé : on ne l'apprend donc qu'une seule fois."},
5:"Jouez la gamme sur deux octaves, dix fois."}},

"mandolin-8":{title:"Mélodie avec accompagnement",goal:"Jouer une chanson entière en y glissant des accords",b:{
0:"Maintenant on combine : mélodie, accords et trémolo dans le même morceau.",
1:"Morceau combiné",
2:"Jouez d'abord la mélodie seule, puis les accords seuls, et seulement ensuite combinez. Combiner trop tôt gâche les deux.",
3:{q:"Comment combiner mélodie et accompagnement ?",o:["Les jouer ensemble dès le début","Apprendre chacun séparément puis combiner","Renoncer à l'un des deux","Jouer très lentement"],w:"Séparer d'abord, combiner ensuite — c'est la voie rapide."},
4:"Jouez le morceau combiné cinq fois."}},

"mandolin-9":{title:"Bilan et suite",goal:"Savoir ce que vous avez appris et où aller",b:{
0:"Vous avez terminé : cordes à vide, notes sur le manche, accords, trémolo et gammes sur deux octaves.",
1:"La suite : le <b>style bluegrass</b> (jeu rapide et précis au médiator), les <b>accords barrés</b> qui se déplacent sur le manche, et <b>l'improvisation</b> sur les gammes apprises.",
2:"Morceau final",
3:"La mandoline partage son accord avec le violon — tout ce que vous avez appris ici se transfère presque intégralement si vous voulez l'essayer.",
4:{q:"Quel instrument partage l'accord de la mandoline ?",o:["La guitare","Le violon","La basse","Le ukulélé"],w:"Les deux sont accordés sol-ré-la-mi."},
5:"Jouez le morceau final et enregistrez-vous."}}

});
